<script setup>
import {computed,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuthStore} from '../stores/auth'
import {useMarketStore} from '../stores/market'
import {CATEGORIES,LOCATIONS} from '../data/seed'
import {notify} from '../lib/ui'
import UploadDropzone from '../components/UploadDropzone.vue'
import CampusMap from '../components/CampusMap.vue'
import Icon from '../components/Icon.vue'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),market=useMarketStore()
const existing=route.params.id?market.product(route.params.id):null
const forbidden=computed(()=>route.params.id&&(!existing||existing.sellerId!==auth.user?.id))
const form=reactive({title:existing?.title||'',category:existing?.category||'books',price:existing?.price||'',originalPrice:existing?.originalPrice||'',condition:existing?.condition||'几乎全新',description:existing?.description||'',story:existing?.story||'',locationId:existing?.locationId||'library',images:existing?.images.slice()||[]})
const showMap=ref(false),busy=ref(false),error=ref('')
async function submit(){error.value='';if(!form.images.length){error.value='先为好物拍一张照片吧';return}busy.value=true;try{const p=await market.saveProduct(auth.user.id,form,existing?.id);notify(existing?'修改已保存':'发布成功，让美好开始下一段旅程');router.push(`/product/${p.id}`)}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="page-width inner-page publish-page"><div class="breadcrumb"><RouterLink to="/">首页</RouterLink><Icon name="chevron" :size="13"/>{{existing?'编辑闲置':'发布闲置'}}</div><div v-if="forbidden" class="empty-state panel"><h2>只能编辑自己发布的闲置</h2><RouterLink to="/profile" class="button primary">返回个人中心</RouterLink></div><template v-else><div class="page-title"><span class="eyebrow">LET THE GOOD THINGS CONTINUE</span><h1>{{existing?'好物的故事，继续完善。':'给闲置一个温柔的新开始。'}}</h1><p>认真介绍它，让下一位主人一眼心动。</p></div><div class="publish-layout"><form class="panel publish-form" @submit.prevent="submit"><section><div class="form-section-title"><span>01</span><h2>让它先露个面</h2><small>第一张照片将作为封面</small></div><UploadDropzone v-model="form.images" @error="message=>notify(message,'error')"/></section><section><div class="form-section-title"><span>02</span><h2>关于这件好物</h2></div><label for="item-title">商品标题 <small>必填</small><input id="item-title" v-model="form.title" required minlength="2" maxlength="60" placeholder="为你的闲置取一个让人心动的名字"/></label><div class="form-row"><label for="item-category">好物分类<select id="item-category" v-model="form.category"><option v-for="category in CATEGORIES" :key="category.id" :value="category.id">{{category.label}}</option></select></label><label for="item-condition">物品成色<select id="item-condition" v-model="form.condition"><option>全新</option><option>几乎全新</option><option>轻微使用</option><option>正常使用</option></select></label></div><div class="form-row"><label for="item-price">转让价 / 元 <small>必填</small><input id="item-price" v-model="form.price" required type="number" min="0.01" max="99999" step="0.01" placeholder="希望以多少价格转让"/></label><label for="item-original">原价 / 元 <small>选填</small><input id="item-original" v-model="form.originalPrice" type="number" :min="Number(form.price)||0" max="999999" step="0.01" placeholder="当时购入的价格"/></label></div><label for="item-description">详细描述 <small>{{form.description.length}} / 2000</small><textarea id="item-description" v-model="form.description" required minlength="5" maxlength="2000" rows="5" placeholder="它的使用情况、配件、尺寸，或需要提前说明的小瑕疵…"/></label><label for="item-story">想对下一位主人说的话 <small>选填</small><textarea id="item-story" v-model="form.story" maxlength="500" rows="3" placeholder="分享一段关于它的校园回忆吧。"/></label></section><section><div class="form-section-title"><span>03</span><h2>约在校园的哪里？</h2></div><div class="form-row location-form-row"><label for="item-location">交接地点<select id="item-location" v-model="form.locationId"><option v-for="place in LOCATIONS" :key="place.id" :value="place.id">{{place.name}}</option></select></label><button type="button" class="button outline" @click="showMap=!showMap"><Icon name="pin" :size="17"/>{{showMap?'收起地图':'在地图上选'}}</button></div><CampusMap v-if="showMap" v-model="form.locationId" compact/></section><p v-if="error" class="form-error" role="alert"><Icon name="info" :size="17"/>{{error}}</p><div class="form-submit"><span><Icon name="shield" :size="16"/>发布即公开，请如实描述物品情况。</span><button class="button primary large" :disabled="busy">{{busy?'正在保存…':existing?'保存修改':'发布，给它找归宿'}}<Icon name="arrow" :size="18"/></button></div></form><aside class="publish-guide"><span class="eyebrow">A LITTLE GUIDE</span><h3>好物被喜欢的<br>小秘诀。</h3><div><span>01</span><h4>拍下真实的样子</h4><p>找一处明亮的自然光，拍清物品全貌，也别忘了细节和小瑕疵。</p></div><div><span>02</span><h4>标一个友好的价格</h4><p>旧物的价值不止标价，让价格也带一点同校同学的温度。</p></div><div><span>03</span><h4>选一个熟悉的地点</h4><p>图书馆前、教学楼下，建议在白天的校园公共区域完成交接。</p></div><Icon name="leaf" :size="52"/><p class="guide-signature">旧物有故事，<br>你是下一章。</p></aside></div></template></div></template>
